/bin/zsh -lc "python3 -c 'import csv,datetime,collections; f=open(\"Semana12/logs_sinteticos.csv\",newline=\"\"); rd=csv.DictReader(f); rows=[]
for r in rd: rows.append((rd.line_num,datetime.datetime.fromisoformat(r[\"timestamp\"]),r))
rows.sort(key=lambda x:x[1]); print(\"physical_lines\",rd.line_num); groups=collections.defaultdict(list)
for n,t,r in rows: groups[tuple(r.items())].append(n)
print(\"identical_row_groups\",[v for v in groups.values() if len(v)>1]); failures=[x for x in rows if x[2][\"event\"]==\"login\" and x[2][\"result\"]==\"failed\"]; delta=datetime.timedelta(minutes=5); seen=set()
for n,t,r in failures:
 w=[x for x in failures if t<=x[1]<=t+delta and x[2][\"ip\"]==r[\"ip\"]]; bf=[x for x in w if x[2][\"user\"]==r[\"user\"]]
 if len(bf)>=6:
  key=(\"brute\",tuple(x[0] for x in bf))
  if key not in seen:
   seen.add(key); print(\"BRUTE\",r[\"ip\"],r[\"user\"],[(x[0],x[1].isoformat()) for x in bf]); end=max(x[1] for x in bf); print(\"POST_SUCCESS\",[x[0] for x in rows if end<x[1]<=end+delta and x[2][\"ip\"]==r[\"ip\"] and x[2][\"user\"]==r[\"user\"] and x[2][\"event\"]==\"login\" and x[2][\"result\"]==\"success\"])
 if len({x[2][\"user\"] for x in w})>=5:
  key=(\"spray\",tuple(x[0] for x in w))
  if key not in seen: seen.add(key); print(\"SPRAY\",r[\"ip\"],[(x[0],x[2][\"user\"]) for x in w])
print(\"TOKEN_ROWS\",[n for n,t,r in rows if \"token=\" in r[\"detail\"]]); print(\"ROLE_ROWS\",[n for n,t,r in rows if r[\"event\"]==\"role_change\" and r[\"result\"]==\"success\" and \"approved=false\" in r[\"detail\"]])'"

